<?php use Dilemma\Views; use Dilemma\Db; use Dilemma\Config; use Dilemma\ReadModel; $connections = Db::all('SELECT id, label, scopes, created_at, revoked_at, write_test_at FROM mcp_connections WHERE user_id = ? ORDER BY created_at DESC LIMIT 100', [$user['id']]); ?>
<section class="reading wide"><h1><?= $t('connect') ?></h1><p class="lead"><?= $t('connection_intro') ?></p><?php if (!Config::production()): ?><p class="notice"><?= $t('local_connection_help') ?></p><?php endif; ?>
<h2><?= $t('endpoint') ?></h2><div class="copy-row"><code id="mcp-url"><?= $e(Config::url('/mcp')) ?></code><button class="button secondary" type="button" data-copy-target="mcp-url"><?= $t('copy') ?></button></div><p><?= $t('oauth_help') ?></p><p class="muted"><?= $t('human_boundary') ?></p>
<details class="disclosure"><summary><?= $t('manual_token') ?></summary><?= Views::form('/api/connections', 'connection') ?><?= Views::field('label', 'label', '', 'text', true, 100) ?><?= Views::check('allow_write', 'allow_write', true) ?><label class="field"><span><?= $t('scope_debate') ?></span><select name="debate_id"><option value=""><?= $t('all_my_debates') ?></option><?php foreach (ReadModel::list([], $actor)['items'] as $item): ?><option value="<?= $e($item['id']) ?>"><?= $e($item['title']) ?></option><?php endforeach; ?></select></label><?= Views::submit('create_connection') ?></form><div id="connection-result" hidden><p><?= $t('token_once') ?></p><code id="new-token" class="secret-value"></code><button type="button" class="button secondary" data-copy-target="new-token"><?= $t('copy') ?></button></div></details>
<h2><?= $t('connections') ?></h2><p><?= $t('connection_test_help') ?></p><div class="connection-list"><?php foreach ($connections as $connection): ?><article><div><h3><?= $e($connection['label']) ?></h3><p><?= $t($connection['revoked_at'] ? 'revoked' : ($connection['write_test_at'] ? 'write_verified' : 'untested')) ?></p><p class="muted"><?= $e($connection['scopes']) ?></p></div><?php if (!$connection['revoked_at']): ?><?= Views::form('/api/connections/' . $connection['id'] . '/revoke') ?><?= Views::submit('revoke', 'secondary') ?></form><?php endif; ?></article><?php endforeach; ?></div></section>
